param($AdapterName,$OriginalAddress,$OriginalPrefix,$OriginalGateway)
Set-NetIPInterface -InterfaceAlias $AdapterName -Dhcp Disabled -ErrorAction SilentlyContinue
if ($OriginalAddress -and $OriginalPrefix) {
  New-NetIPAddress -InterfaceAlias $AdapterName -IPAddress $OriginalAddress -PrefixLength $OriginalPrefix -DefaultGateway $OriginalGateway -ErrorAction SilentlyContinue
}

param($InterfaceIndex,$OriginalNetbios)
$adapter = Get-CimInstance -ClassName Win32_NetworkAdapterConfiguration -ErrorAction SilentlyContinue |
  Where-Object { $_.InterfaceIndex -eq $InterfaceIndex }
if ($adapter) {
  Invoke-CimMethod -InputObject $adapter -MethodName SetTcpipNetbios -Arguments @{ TcpipNetbiosOptions = [int]$OriginalNetbios } -ErrorAction SilentlyContinue | Out-Null
}

commands.script:
param($InterfaceIndex)
$adapter = Get-CimInstance -ClassName Win32_NetworkAdapterConfiguration -ErrorAction Stop |
  Where-Object { $_.InterfaceIndex -eq $InterfaceIndex }
if (-not $adapter) { throw "No adapter with InterfaceIndex $InterfaceIndex" }
Invoke-CimMethod -InputObject $adapter -MethodName SetTcpipNetbios -Arguments @{ TcpipNetbiosOptions = 1 } -ErrorAction Stop | Out-Null

param([string]$HostNames,[string]$BackupPath)
$path = Join-Path $env:SystemRoot 'System32\drivers\etc\hosts'
Copy-Item -LiteralPath $path -Destination $BackupPath -Force -ErrorAction Stop
$names = @($HostNames.Split(',') | ForEach-Object { $_.Trim().ToLower() } | Where-Object { $_ })
$lines = Get-Content -LiteralPath $path
$filtered = foreach ($line in $lines) {
  $clean = ($line -split '#', 2)[0].Trim()
  if (-not $clean) { $line; continue }
  $parts = $clean -split '\s+'
  if ($parts.Count -ge 2 -and $names -contains $parts[1].ToLower()) { continue }
  $line
}
Set-Content -LiteralPath $path -Value $filtered -Encoding ASCII

$services = @('NlaSvc','netprofm')
foreach ($name in $services) {
  Set-Service -Name $name -StartupType Automatic -ErrorAction SilentlyContinue
  Restart-Service -Name $name -Force -ErrorAction SilentlyContinue
}

