param($OriginalProxyEnable,$OriginalProxyServer)
$path = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
Set-ItemProperty -Path $path -Name ProxyEnable -Value ([int]$OriginalProxyEnable) -Type DWord -ErrorAction SilentlyContinue
if ($OriginalProxyServer) {
  Set-ItemProperty -Path $path -Name ProxyServer -Value $OriginalProxyServer -Type String -ErrorAction SilentlyContinue
}

param($OriginalAutoConfigUrl)
if ($OriginalAutoConfigUrl) {
  Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings' -Name AutoConfigURL -Value $OriginalAutoConfigUrl -Type String -ErrorAction SilentlyContinue
}
